import{_ as t,o as e,c as n,ag as s}from"./chunks/framework.i8sMDeRW.js";const g=JSON.parse('{"title":"Aurora/AgentOS 案例：Agent 操作系统的产品设计","description":"","frontmatter":{},"headers":[],"relativePath":"guide/03-cases/aurora-agentos-case-study.md","filePath":"guide/03-cases/aurora-agentos-case-study.md","lastUpdated":1782288443000}'),i={name:"guide/03-cases/aurora-agentos-case-study.md"};function l(r,a,d,p,o,h){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="aurora-agentos-案例-agent-操作系统的产品设计" tabindex="-1">Aurora/AgentOS 案例：Agent 操作系统的产品设计 <a class="header-anchor" href="#aurora-agentos-案例-agent-操作系统的产品设计" aria-label="Permalink to &quot;Aurora/AgentOS 案例：Agent 操作系统的产品设计&quot;">​</a></h1><blockquote><p><strong>2026-05 更新版</strong>：本文将 Aurora/AgentOS 从“多 Agent 编排框架”的旧叙述，更新为面向生产环境的 <strong>Agent Runtime &amp; Governance Platform</strong> 案例。重点关注 MCP / A2A 生态、工具权限、沙箱执行、trace 回放、Agent 预算、持续评估和企业治理。</p></blockquote><hr><h2 id="一、背景" tabindex="-1">一、背景 <a class="header-anchor" href="#一、背景" aria-label="Permalink to &quot;一、背景&quot;">​</a></h2><h3 id="_1-1-行业背景" tabindex="-1">1.1 行业背景 <a class="header-anchor" href="#_1-1-行业背景" aria-label="Permalink to &quot;1.1 行业背景&quot;">​</a></h3><p>2024-2025 年，AI Agent 从概念验证走向产品落地。到 2026 年，Agent 产品的难点已经不再是“能不能让模型调用工具”，而是：</p><ul><li>工具连接标准化后，如何防止工具滥用和越权；</li><li>Agent 自动执行时，如何设置预算、审批、回滚和审计；</li><li>多 Agent 协作时，如何避免错误级联、状态混乱和成本失控；</li><li>企业客户如何获得可回放 trace、策略控制、权限边界和数据隔离；</li><li>MCP、A2A、AGENTS.md 等开放约定普及后，平台如何建立差异化。</li></ul><p>早期 Agent 框架强调 prompt、chain、workflow 和 tool calling。生产环境则更需要一个 <strong>Agent 操作系统</strong>：为 Agent 提供运行时、工具治理、状态管理、可观测性、安全策略和持续评估。</p><h3 id="_1-2-项目起源" tabindex="-1">1.2 项目起源 <a class="header-anchor" href="#_1-2-项目起源" aria-label="Permalink to &quot;1.2 项目起源&quot;">​</a></h3><p>Aurora 项目最初服务于一家企业级 AI 公司。团队在构建客服、数据分析、销售运营、代码审查等 Agent 时发现，单场景 Demo 很容易，但生产化很难：</p><ol><li>Agent 数量从 3-5 个扩展到 50+ 后，依赖和状态迅速复杂化；</li><li>一个 Agent 的错误会通过工具调用和消息传递放大到整个工作流；</li><li>不同 Agent 对同一工具的权限要求不同，简单 API key 模式不可控；</li><li>企业客户要求完整回放“为什么执行了这个动作”；</li><li>成本不再按单次聊天计算，而是按 run、step、工具调用和重试累积。</li></ol><p>因此，Aurora 从内部编排引擎升级为 AgentOS：生产级 Agent 运行时与治理平台。</p><hr><h2 id="二、产品定位" tabindex="-1">二、产品定位 <a class="header-anchor" href="#二、产品定位" aria-label="Permalink to &quot;二、产品定位&quot;">​</a></h2><h3 id="_2-1-核心价值主张" tabindex="-1">2.1 核心价值主张 <a class="header-anchor" href="#_2-1-核心价值主张" aria-label="Permalink to &quot;2.1 核心价值主张&quot;">​</a></h3><blockquote><p><strong>Run agents safely, observably, and economically in production.</strong></p></blockquote><p>AgentOS 的定位不是另一个 Agent Demo 框架，而是 Agent 的生产运行层，类似 Kubernetes 之于容器、API Gateway 之于微服务。</p><p>核心能力：</p><ol><li><strong>Agent Runtime</strong>：管理 Agent run、step、状态、重试、超时和回滚；</li><li><strong>Tool Governance</strong>：工具注册、权限、参数约束、审批、速率限制；</li><li><strong>Context &amp; Memory</strong>：短期状态、长期记忆、组织上下文、权限过滤；</li><li><strong>Observability</strong>：trace、日志、指标、可视化调试、回放；</li><li><strong>Policy &amp; Approval</strong>：风险分级、人工审批、策略网关；</li><li><strong>Continuous Evals</strong>：线上失败样例回流、回归测试、版本对比。</li></ol><h3 id="_2-2-与现有框架的关系" tabindex="-1">2.2 与现有框架的关系 <a class="header-anchor" href="#_2-2-与现有框架的关系" aria-label="Permalink to &quot;2.2 与现有框架的关系&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用层：客服 Agent / 数据分析 Agent / Coding Agent / 内部运营 Agent</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Agent 框架：LangGraph / LlamaIndex / CrewAI / 自研 workflow</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>AgentOS：运行时 | 工具治理 | 权限 | 沙箱 | 记忆 | 评估 | 审计</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>基础设施：LLM / MCP Servers / APIs / DB / Queue / Sandbox / Storage</span></span></code></pre></div><p>AgentOS 不替代上层框架，而是为它们补齐生产级能力。</p><h3 id="_2-3-目标客户" tabindex="-1">2.3 目标客户 <a class="header-anchor" href="#_2-3-目标客户" aria-label="Permalink to &quot;2.3 目标客户&quot;">​</a></h3><table tabindex="0"><thead><tr><th>客户类型</th><th>核心痛点</th><th>AgentOS 价值</th></tr></thead><tbody><tr><td>企业 AI 平台团队</td><td>Agent 分散、权限不可控</td><td>统一运行时和治理</td></tr><tr><td>SaaS 产品团队</td><td>要把 Agent 嵌入现有产品</td><td>工具权限、审计和成本控制</td></tr><tr><td>Coding Agent 团队</td><td>代码执行、PR、文件写入风险高</td><td>沙箱、审批、trace、回滚</td></tr><tr><td>数据分析团队</td><td>Agent 可能访问敏感数据</td><td>权限过滤、SQL 审批、审计</td></tr><tr><td>大型企业 AI CoE</td><td>需要统一标准和治理</td><td>策略模板、评估体系、合规报表</td></tr></tbody></table><hr><h2 id="三、核心设计" tabindex="-1">三、核心设计 <a class="header-anchor" href="#三、核心设计" aria-label="Permalink to &quot;三、核心设计&quot;">​</a></h2><h3 id="_3-1-系统架构" tabindex="-1">3.1 系统架构 <a class="header-anchor" href="#_3-1-系统架构" aria-label="Permalink to &quot;3.1 系统架构&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    Agent 应用层                           │</span></span>
<span class="line"><span>│  Support Agent | Data Agent | Coding Agent | Ops Agent    │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                    Runtime Control Plane                  │</span></span>
<span class="line"><span>│  Run Manager | Step Scheduler | Retry | Timeout | Rollback│</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                    Tool &amp; Context Plane                   │</span></span>
<span class="line"><span>│  Tool Registry | MCP Connector | Permission | Memory      │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                    Safety &amp; Policy Plane                  │</span></span>
<span class="line"><span>│  RBAC/ABAC | Approval | Risk Scoring | Budget | Sandbox   │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                    Observability Plane                    │</span></span>
<span class="line"><span>│  Trace | Logs | Metrics | Replay | Debugger | Eval Store  │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                    Infrastructure Layer                   │</span></span>
<span class="line"><span>│  LLM Providers | APIs | DB | Queue | Vector DB | Storage  │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="_3-2-agent-run-生命周期" tabindex="-1">3.2 Agent run 生命周期 <a class="header-anchor" href="#_3-2-agent-run-生命周期" aria-label="Permalink to &quot;3.2 Agent run 生命周期&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建 run → 载入上下文 → 计划 step → 选择工具 → 策略校验</span></span>
<span class="line"><span>      → 执行动作 → 观察结果 → 记录 trace → 评估是否继续</span></span>
<span class="line"><span>      → 完成 / 等待审批 / 失败 / 回滚</span></span></code></pre></div><p>每个 run 都有：</p><ul><li>run_id；</li><li>用户和组织身份；</li><li>风险等级；</li><li>最大 step 数；</li><li>最大成本预算；</li><li>工具白名单；</li><li>审批规则；</li><li>完整 trace。</li></ul><h3 id="_3-3-工具治理" tabindex="-1">3.3 工具治理 <a class="header-anchor" href="#_3-3-工具治理" aria-label="Permalink to &quot;3.3 工具治理&quot;">​</a></h3><p>工具是 Agent 最大的风险面。AgentOS 采用“工具注册 + 权限 + 参数约束 + 审批”的组合。</p><table tabindex="0"><thead><tr><th>治理项</th><th>说明</th></tr></thead><tbody><tr><td>工具注册</td><td>每个工具必须有 owner、schema、风险等级、审计策略</td></tr><tr><td>最小权限</td><td>Agent 只能调用被授权工具</td></tr><tr><td>参数校验</td><td>使用 JSON Schema / 类型约束 / 业务规则</td></tr><tr><td>动作分级</td><td>只读、低风险写入、高风险写入、外部发送</td></tr><tr><td>人工审批</td><td>高风险动作必须确认</td></tr><tr><td>沙箱执行</td><td>代码、文件和浏览器操作隔离运行</td></tr><tr><td>速率限制</td><td>防止循环调用和成本失控</td></tr><tr><td>审计记录</td><td>输入、参数、结果、审批人全部记录</td></tr></tbody></table><h3 id="_3-4-mcp-a2a-生态下的产品策略" tabindex="-1">3.4 MCP / A2A 生态下的产品策略 <a class="header-anchor" href="#_3-4-mcp-a2a-生态下的产品策略" aria-label="Permalink to &quot;3.4 MCP / A2A 生态下的产品策略&quot;">​</a></h3><p>连接协议标准化会降低工具接入成本，但不会自动解决生产治理。</p><table tabindex="0"><thead><tr><th>标准化带来的变化</th><th>AgentOS 应对</th></tr></thead><tbody><tr><td>工具接入更容易</td><td>提供 MCP server registry 和安全扫描</td></tr><tr><td>Agent 间通信更通用</td><td>提供 A2A 消息审计和边界控制</td></tr><tr><td>项目说明更标准</td><td>支持 AGENTS.md / policy file 版本管理</td></tr><tr><td>schema 更清晰</td><td>自动生成测试和权限规则</td></tr><tr><td>供应链风险上升</td><td>工具来源验证、签名、隔离和风险评分</td></tr></tbody></table><p>关键判断：<strong>协议解决连接问题，AgentOS 解决可信执行问题。</strong></p><hr><h2 id="四、产品关键决策" tabindex="-1">四、产品关键决策 <a class="header-anchor" href="#四、产品关键决策" aria-label="Permalink to &quot;四、产品关键决策&quot;">​</a></h2><h3 id="决策-1-run-级预算优先于全局预算" tabindex="-1">决策 1：Run 级预算优先于全局预算 <a class="header-anchor" href="#决策-1-run-级预算优先于全局预算" aria-label="Permalink to &quot;决策 1：Run 级预算优先于全局预算&quot;">​</a></h3><p>Agent 成本具有尾部风险。全局预算只能防止月度超支，run 级预算才能阻止单个任务无限循环。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run_budget</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_steps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_tool_calls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_duration_seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_credits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  on_exceed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">require_human_approval</span></span></code></pre></div><h3 id="决策-2-高风险动作默认人工审批" tabindex="-1">决策 2：高风险动作默认人工审批 <a class="header-anchor" href="#决策-2-高风险动作默认人工审批" aria-label="Permalink to &quot;决策 2：高风险动作默认人工审批&quot;">​</a></h3><p>AgentOS 将动作分为四类：</p><table tabindex="0"><thead><tr><th>等级</th><th>示例</th><th>策略</th></tr></thead><tbody><tr><td>L1 只读</td><td>搜索、读取文档</td><td>自动执行</td></tr><tr><td>L2 低风险写入</td><td>创建草稿、生成报告</td><td>自动或轻提示</td></tr><tr><td>L3 高风险写入</td><td>发邮件、改配置、提交 PR</td><td>人工确认</td></tr><tr><td>L4 不可逆动作</td><td>支付、删除数据、生产发布</td><td>多人审批 / 默认禁止</td></tr></tbody></table><h3 id="决策-3-trace-是核心产品-不是调试附属品" tabindex="-1">决策 3：Trace 是核心产品，不是调试附属品 <a class="header-anchor" href="#决策-3-trace-是核心产品-不是调试附属品" aria-label="Permalink to &quot;决策 3：Trace 是核心产品，不是调试附属品&quot;">​</a></h3><p>企业客户需要回答：</p><ul><li>Agent 看到了哪些上下文；</li><li>调用了哪些工具；</li><li>为什么选择这个动作；</li><li>谁批准了高风险步骤；</li><li>是否访问了敏感数据；</li><li>失败时如何回滚。</li></ul><p>因此，trace 必须作为一等产品能力，而不是工程日志。</p><h3 id="决策-4-失败样例自动进入评估闭环" tabindex="-1">决策 4：失败样例自动进入评估闭环 <a class="header-anchor" href="#决策-4-失败样例自动进入评估闭环" aria-label="Permalink to &quot;决策 4：失败样例自动进入评估闭环&quot;">​</a></h3><p>线上失败不能只作为客服 ticket 处理。AgentOS 自动把失败 run 转成评估样例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>失败 run → 分类失败原因 → 生成 eval case → 加入回归集 → 下次版本发布前重跑</span></span></code></pre></div><hr><h2 id="五、指标体系" tabindex="-1">五、指标体系 <a class="header-anchor" href="#五、指标体系" aria-label="Permalink to &quot;五、指标体系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标类别</th><th>指标</th></tr></thead><tbody><tr><td>任务结果</td><td>run 成功率、任务完成率、人工接管率</td></tr><tr><td>执行效率</td><td>平均 step、平均运行时长、重试次数</td></tr><tr><td>工具质量</td><td>工具选择正确率、工具执行成功率、参数错误率</td></tr><tr><td>成本</td><td>单 run 成本、P95 run 成本、预算触发率</td></tr><tr><td>安全</td><td>越权拦截率、高风险动作审批率、敏感数据访问率</td></tr><tr><td>可观测性</td><td>trace 完整率、回放成功率、失败归因覆盖率</td></tr><tr><td>业务</td><td>客户续费、Agent 采用率、自动化节省工时</td></tr></tbody></table><hr><h2 id="六、踩坑与教训" tabindex="-1">六、踩坑与教训 <a class="header-anchor" href="#六、踩坑与教训" aria-label="Permalink to &quot;六、踩坑与教训&quot;">​</a></h2><h3 id="_6-1-多-agent-不一定更好" tabindex="-1">6.1 多 Agent 不一定更好 <a class="header-anchor" href="#_6-1-多-agent-不一定更好" aria-label="Permalink to &quot;6.1 多 Agent 不一定更好&quot;">​</a></h3><p>多 Agent 会增加通信成本、协调成本和错误传播风险。只有当任务可并行、角色边界清楚、验证机制明确时，多 Agent 才值得。</p><h3 id="_6-2-工具-schema-是产品设计的一部分" tabindex="-1">6.2 工具 schema 是产品设计的一部分 <a class="header-anchor" href="#_6-2-工具-schema-是产品设计的一部分" aria-label="Permalink to &quot;6.2 工具 schema 是产品设计的一部分&quot;">​</a></h3><p>工具描述、参数名、返回值结构会直接影响 Agent 表现。不要把 schema 当成纯工程细节。</p><h3 id="_6-3-记忆必须有权限和过期策略" tabindex="-1">6.3 记忆必须有权限和过期策略 <a class="header-anchor" href="#_6-3-记忆必须有权限和过期策略" aria-label="Permalink to &quot;6.3 记忆必须有权限和过期策略&quot;">​</a></h3><p>长期记忆如果不绑定用户、组织、来源、时间和权限，会带来隐私和越权风险。</p><h3 id="_6-4-审批不能只是弹窗" tabindex="-1">6.4 审批不能只是弹窗 <a class="header-anchor" href="#_6-4-审批不能只是弹窗" aria-label="Permalink to &quot;6.4 审批不能只是弹窗&quot;">​</a></h3><p>高风险审批必须包含：动作摘要、影响范围、可回滚性、执行人、审批人、审计记录。</p><hr><h2 id="七、pm-可复用清单" tabindex="-1">七、PM 可复用清单 <a class="header-anchor" href="#七、pm-可复用清单" aria-label="Permalink to &quot;七、PM 可复用清单&quot;">​</a></h2><ul><li>[ ] 每个 Agent run 是否有预算和 step 上限；</li><li>[ ] 每个工具是否有 owner、schema、风险等级；</li><li>[ ] 高风险动作是否需要人工审批；</li><li>[ ] 是否支持 MCP 工具来源验证；</li><li>[ ] 是否记录完整 trace；</li><li>[ ] 是否支持 run 回放；</li><li>[ ] 是否支持失败样例进入 eval；</li><li>[ ] 是否支持组织级权限和数据隔离；</li><li>[ ] 是否支持成本按 run / 用户 / 组织拆分；</li><li>[ ] 是否有 Agent 版本回滚机制。</li></ul><hr><h2 id="八、结论" tabindex="-1">八、结论 <a class="header-anchor" href="#八、结论" aria-label="Permalink to &quot;八、结论&quot;">​</a></h2><p>Aurora/AgentOS 的案例说明：Agent 产品的壁垒不在“能不能调用工具”，而在 <strong>能不能安全、可观测、可预算、可审计地持续运行</strong>。</p><p>随着 MCP、A2A、AGENTS.md 等生态标准化，通用连接能力会越来越商品化。真正能形成护城河的是：企业上下文、权限与策略、可信执行、trace 数据、持续评估和业务工作流嵌入。</p>`,74)])])}const u=t(i,[["render",l]]);export{g as __pageData,u as default};
